package com.bom.integration.controller;
import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper; import com.bom.bom.entity.BomHeader; import com.bom.bom.mapper.BomHeaderMapper; import com.bom.bom.service.BomService; import com.bom.common.*; import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.web.bind.annotation.*; import javax.servlet.http.HttpServletRequest; import java.util.*;
@RestController @RequestMapping("/api/open/boms") @RequiredArgsConstructor public class OpenBomController {private final BomHeaderMapper headers;private final BomService service;@Value("${bom.open.api-key:bom-open-key}")private String key;@GetMapping("/{bomNo}/explode")public R<List<Map<String,Object>>> explode(@PathVariable String bomNo,@RequestHeader(value="X-Api-Key",required=false)String api){if(!key.equals(api))throw new BizException("无效的 API Key");BomHeader h=headers.selectOne(new QueryWrapper<BomHeader>().eq("bom_no",bomNo));if(h==null||!"RELEASED".equals(h.getStatus()))throw new BizException("已发布 BOM 不存在");return R.ok(service.explode(h.getId(),null,null));}}
